#include <USBHost.h>
#include <USBHostHIDKeyboard.h>

USBHostHIDKeyboard keyboard;

void setup() {
  Serial.begin(115200);
  keyboard.registerWithHost();
  if (!USBHost.begin()) {
    Serial.println("USB host start failed");
  }
}

void loop() {
  USBHost.task();
  if (keyboard.available()) {
    uint8_t keys[6] = {};
    keyboard.getKeys(keys);
    Serial.printf("HID usage: %u\n", keys[0]);
    keyboard.clear();
  }
}
